package com.jarvis.mobile.actions;
import android.content.*; import android.database.Cursor; import android.hardware.camera2.CameraManager; import android.media.AudioManager; import android.net.Uri; import android.provider.*; import android.view.KeyEvent; import java.util.*; import com.jarvis.mobile.hands.JarvisAccessibilityService;
public class AndroidActionRouter { final Context c; public AndroidActionRouter(Context c){this.c=c;} public String execute(String raw){String l=raw.toLowerCase(Locale.ROOT).trim(); try{ if(l.startsWith("call "))return call(raw.substring(5).trim()); if(l.startsWith("dial "))return launch(new Intent(Intent.ACTION_DIAL,Uri.parse("tel:"+Uri.encode(raw.substring(5).trim()))),"Dialer opened."); if(l.startsWith("text ")||l.startsWith("sms "))return sms(raw.substring(raw.indexOf(' ')+1).trim()); if(l.startsWith("email "))return email(raw.substring(6).trim()); if(l.startsWith("calendar ")||l.startsWith("schedule ")||l.startsWith("add event "))return event(raw.substring(raw.indexOf(' ')+1).trim()); if(l.startsWith("navigate to "))return nav(raw.substring(12).trim()); if(l.startsWith("directions to "))return nav(raw.substring(14).trim()); if(l.startsWith("open "))return open(raw.substring(5).trim()); if(l.startsWith("search "))return launch(new Intent(Intent.ACTION_VIEW,Uri.parse("https://www.google.com/search?q="+Uri.encode(raw.substring(7)))),"Searching."); if(l.startsWith("timer "))return timer(l.substring(6)); if(l.startsWith("alarm "))return alarm(l.substring(6)); if(l.contains("flashlight on"))return torch(true); if(l.contains("flashlight off"))return torch(false); if(l.contains("volume up"))return vol(AudioManager.ADJUST_RAISE); if(l.contains("volume down"))return vol(AudioManager.ADJUST_LOWER); if(l.equals("pause"))return media(KeyEvent.KEYCODE_MEDIA_PAUSE); if(l.equals("play")||l.equals("resume"))return media(KeyEvent.KEYCODE_MEDIA_PLAY); if(l.equals("next")||l.equals("next track"))return media(KeyEvent.KEYCODE_MEDIA_NEXT); if(l.equals("previous")||l.equals("previous track"))return media(KeyEvent.KEYCODE_MEDIA_PREVIOUS); if(l.equals("back")||l.equals("go back"))return JarvisAccessibilityService.back()?"Done.":"Enable Device Control first."; if(l.equals("home")||l.equals("go home"))return JarvisAccessibilityService.home()?"Done.":"Enable Device Control first."; if(l.startsWith("tap "))return JarvisAccessibilityService.clickText(raw.substring(4).trim())?"Done.":"I couldn't find that control."; if(l.startsWith("type "))return JarvisAccessibilityService.typeText(raw.substring(5))?"Done.":"No editable field is focused."; if(l.contains("scroll down"))return JarvisAccessibilityService.scrollForward()?"Done.":"Nothing scrollable found."; if(l.contains("what's on my screen")||l.contains("what is on my screen")||l.equals("read screen")){String s=JarvisAccessibilityService.screenText();return s.isEmpty()?"Enable Device Control first.":s;} }catch(Exception e){return "That action failed: "+e.getMessage();} return null; }
 String launch(Intent i,String ok){i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);c.startActivity(i);return ok;} String open(String target){String t=target.toLowerCase(Locale.ROOT); Intent i=null; if(t.contains("setting"))i=new Intent(Settings.ACTION_SETTINGS); else if(t.contains("camera"))i=new Intent(MediaStore.INTENT_ACTION_STILL_IMAGE_CAMERA); else for(android.content.pm.ApplicationInfo a:c.getPackageManager().getInstalledApplications(0)){CharSequence n=c.getPackageManager().getApplicationLabel(a);if(n!=null&&n.toString().equalsIgnoreCase(target)){i=c.getPackageManager().getLaunchIntentForPackage(a.packageName);break;}} return i==null?"I couldn't find "+target+".":launch(i,"Opened "+target+".");}
 String call(String who){String p=contact(who,ContactsContract.CommonDataKinds.Phone.CONTENT_URI,ContactsContract.CommonDataKinds.Phone.NUMBER);if(p==null)return "I couldn't find a number for "+who+".";try{return launch(new Intent(Intent.ACTION_CALL,Uri.parse("tel:"+Uri.encode(p))),"Calling "+who+".");}catch(SecurityException e){return launch(new Intent(Intent.ACTION_DIAL,Uri.parse("tel:"+Uri.encode(p))),"Call permission is off, so I opened the dialer.");}}
 String sms(String spec){String who=spec,body="";int n=spec.toLowerCase(Locale.ROOT).indexOf(" saying ");if(n>0){who=spec.substring(0,n).trim();body=spec.substring(n+8).trim();}String p=contact(who,ContactsContract.CommonDataKinds.Phone.CONTENT_URI,ContactsContract.CommonDataKinds.Phone.NUMBER);if(p==null&&who.matches("[+0-9() .-]+"))p=who;if(p==null)return "I couldn't find "+who+".";Intent i=new Intent(Intent.ACTION_SENDTO,Uri.parse("smsto:"+Uri.encode(p)));i.putExtra("sms_body",body);return launch(i,"Message ready for "+who+".");}
 String email(String spec){String who=spec,body="";int n=spec.toLowerCase(Locale.ROOT).indexOf(" saying ");if(n>0){who=spec.substring(0,n).trim();body=spec.substring(n+8).trim();}String a=who.contains("@")?who:contact(who,ContactsContract.CommonDataKinds.Email.CONTENT_URI,ContactsContract.CommonDataKinds.Email.ADDRESS);if(a==null)return "I couldn't find an email for "+who+".";Intent i=new Intent(Intent.ACTION_SENDTO,Uri.parse("mailto:"+Uri.encode(a)));i.putExtra(Intent.EXTRA_TEXT,body);return launch(i,"Email ready for "+who+".");}
 String contact(String who,Uri uri,String col){try(Cursor x=c.getContentResolver().query(uri,new String[]{col,ContactsContract.Data.DISPLAY_NAME},ContactsContract.Data.DISPLAY_NAME+" LIKE ?",new String[]{"%"+who+"%"},null)){if(x!=null&&x.moveToFirst())return x.getString(0);}catch(Exception ignored){}return null;}
 String event(String title){long s=System.currentTimeMillis()+3600000L;Intent i=new Intent(Intent.ACTION_INSERT).setData(CalendarContract.Events.CONTENT_URI).putExtra(CalendarContract.Events.TITLE,title).putExtra(CalendarContract.EXTRA_EVENT_BEGIN_TIME,s).putExtra(CalendarContract.EXTRA_EVENT_END_TIME,s+3600000L);return launch(i,"Calendar event ready.");} String nav(String d){return launch(new Intent(Intent.ACTION_VIEW,Uri.parse("geo:0,0?q="+Uri.encode(d))),"Opening directions to "+d+".");}
 String timer(String s){java.util.regex.Matcher m=java.util.regex.Pattern.compile("(\\d+)\\s*(second|seconds|minute|minutes|hour|hours)").matcher(s);int sec=0;while(m.find()){int n=Integer.parseInt(m.group(1));String u=m.group(2);sec+=u.startsWith("hour")?n*3600:u.startsWith("minute")?n*60:n;}if(sec==0)return "Tell me a duration.";Intent i=new Intent(AlarmClock.ACTION_SET_TIMER).putExtra(AlarmClock.EXTRA_LENGTH,sec).putExtra(AlarmClock.EXTRA_SKIP_UI,true);return launch(i,"Timer set.");}
 String alarm(String s){java.util.regex.Matcher m=java.util.regex.Pattern.compile("(\\d{1,2})(?::(\\d{2}))?\\s*(am|pm)?").matcher(s);if(!m.find())return "Tell me a time.";int h=Integer.parseInt(m.group(1)),mi=m.group(2)==null?0:Integer.parseInt(m.group(2));String ap=m.group(3);if("pm".equals(ap)&&h<12)h+=12;if("am".equals(ap)&&h==12)h=0;Intent i=new Intent(AlarmClock.ACTION_SET_ALARM).putExtra(AlarmClock.EXTRA_HOUR,h).putExtra(AlarmClock.EXTRA_MINUTES,mi).putExtra(AlarmClock.EXTRA_SKIP_UI,true);return launch(i,"Alarm set.");}
 String torch(boolean on)throws Exception{CameraManager cm=(CameraManager)c.getSystemService(Context.CAMERA_SERVICE);cm.setTorchMode(cm.getCameraIdList()[0],on);return on?"Flashlight on.":"Flashlight off.";} String vol(int d){((AudioManager)c.getSystemService(Context.AUDIO_SERVICE)).adjustVolume(d,AudioManager.FLAG_SHOW_UI);return "Done.";} String media(int k){AudioManager a=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);a.dispatchMediaKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,k));a.dispatchMediaKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,k));return "Done.";}
}
